package com.example.rokidgeminisecretary;
import android.content.Context;import org.json.*;
public final class RecorderImportStatusTest {static class Wire extends java.net.Socket {final java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();public java.io.OutputStream getOutputStream(){return out;}String text()throws Exception{return out.toString("UTF-8");}}static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("import status "+n);}public static int run(Context c,String apk)throws Exception{n=0;long now=100000;ok(RecorderImportStatus.label(new JSONObject(),0,now).contains("グラス内"));ok(RecorderImportStatus.label(new JSONObject(),now,now).contains("確認待ち"));ok(RecorderImportStatus.label(new JSONObject(),now-30001,now).contains("未確認"));for(String phase:new String[]{"RUNNING","PARTIAL","FAILED","COMPLETED","INTERRUPTED"}){JSONObject row=new JSONObject().put("kind","photo").put("phase",phase).put("expected",10).put("confirmed",phase.equals("COMPLETED")?10:3).put("startedAt",now-1000).put("updatedAt",now);JSONObject state=new JSONObject().put("connected",true).put("transfers",new JSONArray().put(row));ok(!RecorderImportStatus.label(state,now-1000,now).contains("前回受信"));state.put("connected",false);ok(RecorderImportStatus.label(state,now-1000,now).contains("前回受信"));ok(RecorderImportStatus.label(state,now+10000,now+10000).contains("確認待ち"));}c.getSharedPreferences("phone_secretary",0).edit().clear().commit();{java.lang.reflect.Field pending=MainActivity.class.getDeclaredField("pendingCommand");pending.setAccessible(true);pending.set(null,"");}for(String wire:new String[]{"synthetic question","__LOKI_PHOTO_SYNC__","__LOKI_PHOTO_SYNC__","__LOKI_IMAGE__:synthetic","__LOKI_PHOTO_COPY__"})ok(MainActivity.queueBridgeCommand(c,wire,true));JSONObject request=MainActivity.queuePhotoImport(c,false);ok(request.getString("mode").equals("copy"));ok(request.getInt("superseded")==3);JSONArray kept=new JSONArray(c.getSharedPreferences("phone_secretary",0).getString("pending_command_queue","[]"));ok(kept.length()==2&&kept.getString(0).equals("synthetic question")&&kept.getString(1).equals("__LOKI_IMAGE__:synthetic"));long at=request.getLong("createdAt");String id=request.getString("id");ok(PhotoImportRequests.peek(c,at).has("request"));ok(!PhotoImportRequests.peek(c,at-1).has("request"));ok(PhotoImportRequests.peek(c,at+PhotoImportRequests.TTL).has("request"));ok(!PhotoImportRequests.peek(c,at+PhotoImportRequests.TTL+1).has("request"));ok(!PhotoImportRequests.accept(c,"wrong",at).optBoolean("execute"));JSONObject accepted=PhotoImportRequests.accept(c,id,at+1);ok(accepted.optBoolean("execute"));ok(PhotoImportRequests.accept(c,id,at+2).getJSONObject("request").getLong("acceptedAt")==at+1);ok(RecorderImportStatus.label(new JSONObject(),PhotoImportRequests.current(c),at,at+3).contains("受信しました"));ok(RecorderImportStatus.label(new JSONObject(),PhotoImportRequests.current(c),at,at+30002).contains("開始を確認できません"));JSONObject newer=MainActivity.queuePhotoImport(c,true);ok(newer.optString("mode").equals("move")&&!newer.optString("id").equals(id));ok(!PhotoImportRequests.accept(c,id,at+3).optBoolean("execute"));ok(RecorderImportStatus.label(new JSONObject(),newer,at,at+PhotoImportRequests.TTL+1000).contains("期限"));c.getSharedPreferences("phone_secretary",0).edit().clear().commit();{java.lang.reflect.Field pending=MainActivity.class.getDeclaredField("pendingCommand");pending.setAccessible(true);pending.set(null,"");}c.getSharedPreferences("recorder_import_ui",0).edit().putLong("requestedAt",System.currentTimeMillis()).commit();MainActivity.queueBridgeCommand(c,"synthetic question",true);MainActivity.queueBridgeCommand(c,"__LOKI_PHOTO_SYNC__",true);ok(!MainActivity.resumeQueuedPhotoCopy(c,System.currentTimeMillis()));MainActivity.queueBridgeCommand(c,"__LOKI_PHOTO_COPY__",true);ok(MainActivity.resumeQueuedPhotoCopy(c,System.currentTimeMillis()));ok(PhotoImportRequests.current(c).optString("mode").equals("copy"));ok(!MainActivity.resumeQueuedPhotoCopy(c,System.currentTimeMillis()));JSONArray remaining=new JSONArray(c.getSharedPreferences("phone_secretary",0).getString("pending_command_queue","[]"));ok(remaining.length()==1&&remaining.getString(0).equals("synthetic question"));MainActivity owner=new MainActivity();java.lang.reflect.Method attach=android.content.ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);String token="f".repeat(64);for(String scope:new String[]{"read","full"}){c.getSharedPreferences("loki_web_console",0).edit().putString("sessions",new JSONArray().put(new JSONObject().put("hash",RecorderPhotoStore.hash(token.getBytes("UTF-8"))).put("scope",scope).put("expires",System.currentTimeMillis()+600000)).toString()).commit();String before=PhotoImportRequests.current(c).getString("id");Wire socket=new Wire();LokiWebConsole.handle(owner,socket,"POST /web/api/import HTTP/1.1","{}",token,"","fixture");if(scope.equals("read")){ok(socket.text().startsWith("HTTP/1.1 403"));ok(PhotoImportRequests.current(c).getString("id").equals(before));}else{ok(socket.text().startsWith("HTTP/1.1 200"));ok(PhotoImportRequests.current(c).getString("mode").equals("copy"));ok(new JSONArray(c.getSharedPreferences("phone_secretary",0).getString("pending_command_queue","[]")).length()==1);}}return n;}}
